//! Embed the workspace template into the binary.
//!
//! Walks `<repo>/templates/workspace` (managed files) and `<repo>/templates/seed`
//! (seed-once files) and generates `$OUT_DIR/template_table.rs`:
//!
//! ```ignore
//! pub static ENTRIES: &[Entry] = &[
//!     Entry { path: "AGENTS.md", kind: Kind::Managed, mode: 0o644, bytes: include_bytes!(..) },
//! ];
//! pub const ENGINE: &str = "0.1.0+abc1234";
//! ```
//!
//! `include_bytes!` keeps the bytes out of the source string (a `herdr-gate.sh`
//! with `"#` inside would break a generated byte-string literal).
//!
//! Both directories are required and must hold files: the template is the only
//! source `quaqua init` has, so a missing one fails the build instead of
//! producing a binary that silently bootstraps an empty workspace.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;

const TEMPLATE_DIRS: &[(&str, &str)] = &[("workspace", "Managed"), ("seed", "Seed")];

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let repo = manifest
        .join("../..")
        .canonicalize()
        .unwrap_or_else(|_| manifest.join("../.."));
    let templates = repo.join("templates");

    let mut entries: Vec<(String, String, String, u32)> = Vec::new(); // rel, kind, include, mode
    for (dir, kind) in TEMPLATE_DIRS {
        let base = templates.join(dir);
        println!("cargo:rerun-if-changed={}", base.display());
        if !base.is_dir() {
            panic!(
                "build.rs: missing template dir {} — `quaqua init` embeds \
                 templates/workspace and templates/seed, so a build needs a full checkout",
                base.display()
            );
        }
        let before = entries.len();
        walk(&base, &base, &repo, &mut entries, kind)
            .unwrap_or_else(|e| panic!("build.rs: cannot read {}: {e}", base.display()));
        if entries.len() == before {
            panic!(
                "build.rs: {} holds no files — an empty template would bootstrap an empty workspace",
                base.display()
            );
        }
    }
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let mut src = String::new();
    src.push_str("// @generated by build.rs — do not edit.\n");
    src.push_str("pub static ENTRIES: &[Entry] = &[\n");
    for (rel, kind, abs, mode) in &entries {
        src.push_str(&format!(
            "    Entry {{ path: {rel:?}, kind: Kind::{kind}, mode: 0o{mode:o}, \
             bytes: include_bytes!(concat!(env!(\"CARGO_MANIFEST_DIR\"), \"/../..{abs}\")) }},\n",
        ));
    }
    src.push_str("];\n");
    src.push_str(&format!(
        "pub const ENGINE: &str = \"{}+{}\";\n",
        std::env::var("CARGO_PKG_VERSION").unwrap_or_default(),
        git_sha(&manifest),
    ));

    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR")).join("template_table.rs");
    write_if_changed(&out, &src).unwrap_or_else(|e| panic!("cannot write {}: {e}", out.display()));
}

/// Recursive walk. `path` is relative to the template subdir (`base`); `include`
/// is `<repo-relative path>` so the generated `include_bytes!` never embeds an
/// absolute machine path.
fn walk(
    base: &Path,
    dir: &Path,
    repo: &Path,
    out: &mut Vec<(String, String, String, u32)>,
    kind: &str,
) -> io::Result<()> {
    for ent in fs::read_dir(dir)? {
        let path = ent?.path();
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();
        if name == ".git" || name == ".DS_Store" {
            continue;
        }
        println!("cargo:rerun-if-changed={}", path.display());
        let meta = fs::metadata(&path)?;
        if meta.is_dir() {
            walk(base, &path, repo, out, kind)?;
        } else if meta.is_file() {
            let rel = path
                .strip_prefix(base)
                .map(|p| p.to_string_lossy().replace('\\', "/"))
                .unwrap_or(name);
            let include = path
                .strip_prefix(repo)
                .map(|p| format!("/{}", p.to_string_lossy().replace('\\', "/")))
                .unwrap_or_else(|_| format!("/{rel}"));
            out.push((rel, kind.to_string(), include, mode_of(&meta)));
        }
    }
    Ok(())
}

#[cfg(unix)]
fn mode_of(meta: &fs::Metadata) -> u32 {
    use std::os::unix::fs::PermissionsExt;
    meta.permissions().mode() & 0o777
}

#[cfg(not(unix))]
fn mode_of(_meta: &fs::Metadata) -> u32 {
    0o644
}

/// `<short sha>` of the checkout being built; `unknown` outside a git checkout
/// (`cargo install --git` builds inside one, a tarball does not).
fn git_sha(manifest: &Path) -> String {
    Command::new("git")
        .arg("-C")
        .arg(manifest)
        .args(["rev-parse", "--short=7", "HEAD"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown".to_string())
}

/// Keep the OUT_DIR file stable so an unchanged template does not force a
/// rebuild of every dependent crate.
fn write_if_changed(path: &Path, content: &str) -> io::Result<()> {
    if let Ok(old) = fs::read_to_string(path) {
        if old == content {
            return Ok(());
        }
    }
    fs::write(path, content)
}
